"""Visualize midpoints generated by the LTRL z-proposal network.

For given (start, goal) pairs, samples z from the iMF proposal network, then
uses a trained linear probe to decode z -> (x, y) and plots on the maze.

Usage:
    uv run python viz_midpoints.py \
        --exp_dir=exp/OGBench/ltrl-hmaze-giant-stitch-100m-cf/sd000_... \
        --epoch=1000000 \
        --env_name=humanoidmaze-giant-navigate-v0
"""

import json
import pathlib
import pickle

import jax
import jax.numpy as jnp
import matplotlib.pyplot as plt
import numpy as np
from absl import app, flags
from ml_collections import ConfigDict
import ogbench

FLAGS = flags.FLAGS

flags.DEFINE_string('exp_dir', None, 'Experiment directory.')
flags.DEFINE_integer('epoch', 1000000, 'Checkpoint epoch.')
flags.DEFINE_string('env_name', 'humanoidmaze-giant-v0', 'Environment name.')
flags.DEFINE_string('dataset_path', None, 'Dataset path (default: from flags.json).')
flags.DEFINE_integer('n_probe_samples', 50000, 'Samples for training the linear probe.')
flags.DEFINE_integer('n_midpoint_pairs', 200, 'Number of (start, goal) pairs to visualize.')
flags.DEFINE_integer('n_z_per_pair', 5, 'Number of z samples per (start, goal) pair.')
flags.DEFINE_string('output', None, 'Output path (default: <exp_dir>/midpoints.png).')


def load_agent(exp_dir, epoch, env):
    """Load LTRL agent from checkpoint."""
    with open(f'{exp_dir}/flags.json', 'r') as f:
        flag_dict = json.load(f)

    config = ConfigDict(flag_dict['agent'])

    from agents.latent_trl import LatentTRLAgent

    ob_dim = env.observation_space.shape[0]
    action_dim = env.action_space.shape[0]
    batch_size = 2
    example_batch = {
        'observations': np.zeros((batch_size, ob_dim)),
        'actions': np.zeros((batch_size, action_dim)),
        'actor_goals': np.zeros((batch_size, ob_dim)),
        'value_midpoint_observations': np.zeros((batch_size, ob_dim)),
    }
    agent = LatentTRLAgent.create(seed=0, example_batch=example_batch, config=config)

    params_path = f'{exp_dir}/params_{epoch}.pkl'
    with open(params_path, 'rb') as f:
        load_dict = pickle.load(f)
    import flax.serialization
    agent = flax.serialization.from_state_dict(agent, load_dict['agent'])
    print(f'Loaded {params_path}')
    return agent, flag_dict


def load_dataset(dataset_path):
    """Load dataset. Handles both single .npz and sharded directory."""
    p = pathlib.Path(dataset_path)
    if p.is_dir():
        # Sharded dataset: load first non-val shard.
        shards = sorted(f for f in p.glob('*.npz') if 'val' not in f.name)
        if not shards:
            raise FileNotFoundError(f'No .npz shards in {dataset_path}')
        print(f'Loading shard: {shards[0].name}')
        data = np.load(str(shards[0]))
    else:
        data = np.load(dataset_path)
    return dict(data)


def get_maze_info(env):
    maze_env = env.unwrapped
    return maze_env.maze_map, maze_env._maze_unit, maze_env._offset_x, maze_env._offset_y


def make_observation_at_xy(env, xy):
    env.reset()
    env.unwrapped.set_xy(np.array(xy))
    import mujoco
    mujoco.mj_forward(env.unwrapped.model, env.unwrapped.data)
    return env.unwrapped.get_ob().astype(np.float32)


def draw_maze_walls(ax, maze_map, maze_unit, offset_x, offset_y):
    rows, cols = maze_map.shape
    for i in range(rows):
        for j in range(cols):
            if maze_map[i, j] == 1:
                wx = j * maze_unit - offset_x
                wy = i * maze_unit - offset_y
                rect = plt.Rectangle(
                    (wx - maze_unit / 2, wy - maze_unit / 2),
                    maze_unit, maze_unit,
                    facecolor='#cccccc', edgecolor='#999999', linewidth=0.5,
                )
                ax.add_patch(rect)


class LinearProbe:
    """Simple ridge regression probe using JAX: z -> (x, y)."""

    def __init__(self, alpha=1.0):
        self.alpha = alpha
        self.W = None  # (z_dim, 2)
        self.b = None  # (2,)

    def fit(self, Z, Y):
        """Fit W, b via closed-form ridge: min ||ZW + b - Y||^2 + alpha * ||W||^2."""
        Z = jnp.array(Z, dtype=jnp.float32)
        Y = jnp.array(Y, dtype=jnp.float32)
        # Augment Z with ones for bias.
        n, d = Z.shape
        Z_aug = jnp.concatenate([Z, jnp.ones((n, 1))], axis=1)  # (n, d+1)
        reg = self.alpha * jnp.concatenate([jnp.ones(d), jnp.zeros(1)])  # Don't regularize bias.
        A = Z_aug.T @ Z_aug + jnp.diag(reg)
        sol = jnp.linalg.solve(A, Z_aug.T @ Y)  # (d+1, 2)
        self.W = sol[:d]
        self.b = sol[d]

    def predict(self, Z):
        Z = jnp.array(Z, dtype=jnp.float32)
        return np.array(Z @ self.W + self.b)


def train_probe(agent, dataset, n_samples):
    """Train a linear probe: z = enc(obs) -> (x, y).

    The humanoidmaze observation starts with [x, y, ...], so ground truth
    is obs[:2].
    """
    observations = dataset['observations']
    n_total = len(observations)
    idxs = np.random.choice(n_total, size=min(n_samples, n_total), replace=False)
    obs_sample = observations[idxs].astype(np.float32)
    xy_gt = obs_sample[:, :2]

    # Encode through the state encoder and then the midpoint encoder in batches.
    batch_size = 4096
    z_list = []
    for i in range(0, len(obs_sample), batch_size):
        batch_obs = jnp.array(obs_sample[i:i + batch_size])
        u = agent._encode_state(batch_obs)
        z = agent._encode_subgoal(u)
        z_list.append(np.array(z))
    z_all = np.concatenate(z_list, axis=0)

    # Fit linear probe: z -> xy.
    probe = LinearProbe(alpha=1.0)
    probe.fit(z_all, xy_gt)

    # Report probe quality.
    xy_pred = probe.predict(z_all)
    mse = float(np.mean((xy_pred - xy_gt) ** 2))
    ss_res = float(np.sum((xy_pred - xy_gt) ** 2))
    ss_tot = float(np.sum((xy_gt - xy_gt.mean(0)) ** 2))
    r2 = 1.0 - ss_res / ss_tot
    print(f'Probe: MSE={mse:.4f}, R²={r2:.4f} (on {len(z_all)} samples)')

    return probe


def sample_midpoints(agent, obs_start, obs_goal, n_z, rng_key):
    """Sample z midpoints from the proposal network for given (s, g) pairs."""
    z_dim = agent.config['z_dim']

    from utils.flows import imf_one_shot_sample

    n_pairs = obs_start.shape[0]
    u_start = agent._encode_state(obs_start)
    u_goal = agent._encode_state(obs_goal)
    u_start, u_goal = agent._proposal_context(u_start, u_goal)

    def vector_field_fn(noise, times):
        # noise/times: (n_z, n_pairs, z_dim/5) - need to broadcast obs to match.
        obs_bc = jnp.broadcast_to(u_start[None], (n_z, n_pairs, u_start.shape[-1]))
        goals_bc = jnp.broadcast_to(u_goal[None], (n_z, n_pairs, u_goal.shape[-1]))
        out = agent.network.select('z_proposal')(
            obs_bc.reshape(-1, u_start.shape[-1]),
            goals=goals_bc.reshape(-1, u_goal.shape[-1]),
            actions=noise.reshape(-1, z_dim),
            times=times.reshape(-1, times.shape[-1]),
        )
        return out.reshape(n_z, n_pairs, z_dim)

    sample_shape = (n_z, n_pairs, z_dim)
    z_samples = imf_one_shot_sample(rng_key, sample_shape, vector_field_fn)
    return z_samples  # (n_z, n_pairs, z_dim)


def decode_midpoints(agent, obs_start, obs_goal, z_midpoints, rng_key):
    """Decode proposed midpoint latents through the actual grounded path.

    z -> midpoint_decoder(u_s, u_g, z) -> u_mid -> vae_decoder(u_mid) -> obs_hat
    """
    n_z, n_pairs, _ = z_midpoints.shape
    u_start = agent._encode_state(obs_start)
    u_goal = agent._encode_state(obs_goal)
    u_mid = agent._sample_midpoint_decoder(u_start, u_goal, z_midpoints, rng_key, num_samples=n_z)
    u_mid_flat = u_mid.reshape(-1, u_mid.shape[-1])
    obs_mid_flat = np.array(agent.network.select('vae_decoder')(u_mid_flat))
    return obs_mid_flat.reshape(n_z, n_pairs, -1)


def main(_):
    np.random.seed(42)

    env = ogbench.make_env_and_datasets(
        FLAGS.env_name,
        dataset_path=FLAGS.dataset_path,
        env_only=True,
        terminate_at_goal=False,
        max_episode_steps=1000,
    )
    maze_map, maze_unit, offset_x, offset_y = get_maze_info(env)

    exp_dir = FLAGS.exp_dir
    agent, flag_dict = load_agent(exp_dir, FLAGS.epoch, env)

    # Load dataset.
    dataset_path = FLAGS.dataset_path or flag_dict.get('dataset_path')
    if not dataset_path:
        raise ValueError('No dataset_path found. Specify --dataset_path.')
    print(f'Loading dataset from {dataset_path}...')
    dataset = load_dataset(dataset_path)
    print(f'Dataset: {dataset["observations"].shape[0]} transitions, obs_dim={dataset["observations"].shape[1]}')

    # Train linear probe.
    probe = train_probe(agent, dataset, FLAGS.n_probe_samples)

    # Sample diverse (start, goal) pairs from the dataset.
    observations = dataset['observations']
    n_total = len(observations)
    n_pairs = FLAGS.n_midpoint_pairs
    start_idxs = np.random.choice(n_total, size=n_pairs, replace=False)
    goal_idxs = np.random.choice(n_total, size=n_pairs, replace=False)

    obs_start = jnp.array(observations[start_idxs].astype(np.float32))
    obs_goal = jnp.array(observations[goal_idxs].astype(np.float32))

    xy_start = observations[start_idxs, :2]
    xy_goal = observations[goal_idxs, :2]

    # Filter to pairs with reasonable distance (skip trivially close ones).
    dists = np.linalg.norm(xy_start - xy_goal, axis=1)
    far_mask = dists > 4.0  # At least 4 units apart.
    if far_mask.sum() < 10:
        far_mask = dists > np.median(dists)
    obs_start = obs_start[far_mask]
    obs_goal = obs_goal[far_mask]
    xy_start = xy_start[far_mask]
    xy_goal = xy_goal[far_mask]
    n_pairs = len(xy_start)
    print(f'Using {n_pairs} (start, goal) pairs with dist > threshold')

    # Sample z midpoints from proposal.
    n_z = FLAGS.n_z_per_pair
    rng_key = jax.random.PRNGKey(0)
    z_midpoints = sample_midpoints(agent, obs_start, obs_goal, n_z, rng_key)
    # z_midpoints: (n_z, n_pairs, z_dim)

    # Decode proposals through the actual midpoint path when available.
    if hasattr(agent, '_sample_midpoint_decoder') and hasattr(agent, '_encode_state'):
        decode_rng = jax.random.PRNGKey(1)
        obs_mid_pred = decode_midpoints(agent, obs_start, obs_goal, z_midpoints, decode_rng)
        xy_mid_pred = obs_mid_pred[..., :2]
        midpoint_label = 'Proposed midpoint (decoded)'
    else:
        # Fallback for older agents: decode z -> xy via probe.
        z_flat = np.array(z_midpoints.reshape(-1, agent.config['z_dim']))
        xy_mid_pred = probe.predict(z_flat)  # (n_z * n_pairs, 2)
        xy_mid_pred = xy_mid_pred.reshape(n_z, n_pairs, 2)
        midpoint_label = 'Proposed midpoint (probe)'

    # Also encode actual midpoint observations from dataset and decode to verify probe.
    # For each pair, get the z of the actual start and goal to confirm probe accuracy.
    z_start = np.array(agent._encode_subgoal(agent._encode_state(obs_start)))
    z_goal = np.array(agent._encode_subgoal(agent._encode_state(obs_goal)))
    xy_start_decoded = probe.predict(z_start)
    xy_goal_decoded = probe.predict(z_goal)

    # --- Plot ---
    rows, cols = maze_map.shape
    x_min = 0 * maze_unit - offset_x - maze_unit / 2
    x_max = (cols - 1) * maze_unit - offset_x + maze_unit / 2
    y_min = 0 * maze_unit - offset_y - maze_unit / 2
    y_max = (rows - 1) * maze_unit - offset_y + maze_unit / 2

    fig, axes = plt.subplots(1, 2, figsize=(16, 8))

    # --- Left panel: all midpoints colored by pair ---
    ax = axes[0]
    draw_maze_walls(ax, maze_map, maze_unit, offset_x, offset_y)

    # Color each pair differently.
    cmap = plt.cm.tab20
    n_show = min(n_pairs, 40)  # Show at most 40 pairs to avoid clutter.
    for i in range(n_show):
        color = cmap(i % 20)
        # Draw start and goal.
        ax.plot(xy_start[i, 0], xy_start[i, 1], 'o', color=color, markersize=6,
                markeredgecolor='black', markeredgewidth=0.5, zorder=5)
        ax.plot(xy_goal[i, 0], xy_goal[i, 1], 's', color=color, markersize=6,
                markeredgecolor='black', markeredgewidth=0.5, zorder=5)
        # Draw midpoints.
        for k in range(n_z):
            ax.plot(xy_mid_pred[k, i, 0], xy_mid_pred[k, i, 1], '*', color=color,
                    markersize=8, markeredgecolor='black', markeredgewidth=0.3, zorder=4)
        # Lines from start to midpoints to goal.
        for k in range(n_z):
            ax.plot([xy_start[i, 0], xy_mid_pred[k, i, 0]],
                    [xy_start[i, 1], xy_mid_pred[k, i, 1]],
                    '-', color=color, alpha=0.3, linewidth=0.8)
            ax.plot([xy_mid_pred[k, i, 0], xy_goal[i, 0]],
                    [xy_mid_pred[k, i, 1], xy_goal[i, 1]],
                    '--', color=color, alpha=0.3, linewidth=0.8)

    ax.set_xlim(x_min, x_max)
    ax.set_ylim(y_min, y_max)
    ax.set_aspect('equal')
    ax.set_title(f'Proposed midpoints ({n_show} pairs, {n_z} z/pair)')
    ax.legend(
        [plt.Line2D([0], [0], marker='o', color='gray', linestyle=''),
         plt.Line2D([0], [0], marker='s', color='gray', linestyle=''),
         plt.Line2D([0], [0], marker='*', color='gray', linestyle='', markersize=10)],
        ['Start', 'Goal', midpoint_label],
        loc='upper right', fontsize=8,
    )

    # --- Right panel: density heatmap of all midpoints ---
    ax2 = axes[1]
    draw_maze_walls(ax2, maze_map, maze_unit, offset_x, offset_y)

    # All midpoints as scatter.
    xy_all_mid = xy_mid_pred.reshape(-1, 2)
    ax2.scatter(xy_all_mid[:, 0], xy_all_mid[:, 1], c='red', s=4, alpha=0.4, zorder=3)
    # Also show dataset xy distribution for reference.
    dataset_xy = observations[np.random.choice(n_total, size=min(5000, n_total), replace=False), :2]
    ax2.scatter(dataset_xy[:, 0], dataset_xy[:, 1], c='blue', s=1, alpha=0.1, zorder=2, label='Dataset')
    ax2.scatter(xy_all_mid[:, 0], xy_all_mid[:, 1], c='red', s=4, alpha=0.4, zorder=3, label=midpoint_label)

    ax2.set_xlim(x_min, x_max)
    ax2.set_ylim(y_min, y_max)
    ax2.set_aspect('equal')
    ax2.set_title(f'Midpoint distribution (all {len(xy_all_mid)} points)')
    ax2.legend(fontsize=8, loc='upper right')

    output = FLAGS.output or f'{exp_dir}/midpoints.png'
    plt.tight_layout()
    plt.savefig(output, dpi=150, bbox_inches='tight')
    print(f'Saved to {output}')
    plt.close()

    # --- Additional plot: probe quality check ---
    fig2, ax3 = plt.subplots(1, 1, figsize=(8, 8))
    draw_maze_walls(ax3, maze_map, maze_unit, offset_x, offset_y)

    # Show ground truth vs decoded positions for starts.
    for i in range(min(50, n_pairs)):
        ax3.plot([xy_start[i, 0], xy_start_decoded[i, 0]],
                 [xy_start[i, 1], xy_start_decoded[i, 1]],
                 'b-', alpha=0.3, linewidth=0.5)
    ax3.scatter(xy_start[:50, 0], xy_start[:50, 1], c='blue', s=20, label='GT', zorder=5)
    ax3.scatter(xy_start_decoded[:50, 0], xy_start_decoded[:50, 1], c='red', s=20,
                marker='x', label='Probe decoded', zorder=5)

    ax3.set_xlim(x_min, x_max)
    ax3.set_ylim(y_min, y_max)
    ax3.set_aspect('equal')
    ax3.set_title('Probe quality: GT (blue) vs decoded (red x)')
    ax3.legend(fontsize=8)

    probe_output = output.replace('.png', '_probe_check.png')
    plt.savefig(probe_output, dpi=150, bbox_inches='tight')
    print(f'Saved probe check to {probe_output}')
    plt.close()


if __name__ == '__main__':
    app.run(main)
